// test_parse_quantity.cpp (plain asserts; frameworks like GoogleTest or Catch2 work the same way).
#include <cassert>
#include <optional>
#include <string>

std::optional<int> parse_quantity(const std::string& line);   // accepts 1..99.

int main() {
    // Normal.
    assert(parse_quantity("3") == 3);
    // Boundaries.
    assert(parse_quantity("1") == 1);
    assert(parse_quantity("99") == 99);
    assert(!parse_quantity("0"));
    assert(!parse_quantity("100"));
    // Malformed and empty.
    assert(!parse_quantity(""));
    assert(!parse_quantity("two"));
    assert(!parse_quantity("3x"));
    assert(!parse_quantity("-5"));
    return 0;                     // all behaviours hold.
}
```

